(7426228, 1172804, 65234, '<td valign="top">Beautifully seen and processed; rich tones.</td>', 'Beautifully seen and processed; rich tones.', '2016-01-07 13:01:40.000000', NULL, 1),
(7426229, 1172677, 65234, '<td valign="top">I would love to join them :-)</td>', 'I would love to join them :-)', '2016-01-07 13:02:23.000000', NULL, 1),
(7426230, 1172657, 65234, '<td valign="top">A 2-fer wildlife capture!</td>', 'A 2-fer wildlife capture!', '2016-01-07 13:02:42.000000', NULL, 1),
